globalThis.nameGen = function (type) {
	let lname = "";
	let nMs = "";

	for(i = 0; i < 16; i++){
		if (Math.random() < 0.5) {
			// Use nameSur() as before
			nameSur();
			while (lname === "") {
				nameSur();
			}
		} else {
			// Select from nm85
			var rnd85 = Math.floor(Math.random() * nm85.length);
			lname = nm85[rnd85];
		}
		if (tp === 'f') {
			if (Math.random() < 0.5) {
				// Use nameFem() as before
				nameFem();
				while (nMs === "") {
					nameFem();
				}
			} else {
				// Select from nm84
				let rnd = Math.floor(Math.random() * nm84.length);
				nMs = nm84[rnd];
			}
		}
		else if (tp === 'm') {
			if (Math.random() < 0.5) {
				// Use nameMas() as before
				nameMas();
				while (nMs === "") {
					name();
				}
			} else {
				// Select from nm83
				let rnd = Math.floor(Math.random() * nm83.length);
				nMs = nm83[rnd];
			}
		}
		return nMs + " " + lname;
	};

	// If run directly from CLI:
	if (require.main === module) {
		const type = process.argv[2] || 'm';
		console.log(globalThis.nameGen(type));
	}
}	


